// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    // Fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep depositor non-zero and amount within reasonable bounds to avoid overflow
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund the depositor so they can deposit
        vm.deal(depositor, amount);

        // depositor makes a deposit
        vm.prank(depositor);
        c.deposit{value: amount}();

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // call withdrawAll as the depositor and observe whether it reverts
        bool ok;
        vm.prank(depositor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful withdraw on the correct contract:
        //  - the contract's balance decreases by exactly `amount`
        //  - and withdraw succeeded (ok == true)
        // For the mutant that reads credit[address(this)] the withdraw may send 0 or some other amount
        // and may revert depending on call return; thus there exist inputs where the invariant fails.

        // We assert the universal property: if withdraw returned successfully then the contract's balance
        // must have decreased by exactly `amount` (the depositor's recorded credit), i.e. address(c).balance == before - amount.
        // This holds for the reference implementation for all inputs, but can be violated by the mutant.

        if (ok) {
            assertTrue(address(c).balance == before - amount);
        } else {
            // If withdraw reverted, then we cannot assert balance change; still allow the fuzz run to pass for cases
            // where withdraw legitimately reverted. The key assertion is inside the ok branch above.
            assertTrue(true);
        }
    }
}
